using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // 1. Discriminator: EF Core 9 defaults to "$type" instead of "Discriminator".
        //    Preserve the old property name so existing documents are still found.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // 2. Id format: EF Core 9 defaults to just the key value instead of "EntityType|Key".
        //    Preserve the old "Blog|{Id}" format for existing documents.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id");
        modelBuilder.Entity<Blog>().UseETagConcurrency();

        // 3. HasIndex: Cosmos provider now throws on HasIndex (never supported).
        //    Removed the previous HasIndex(b => b.Name) call.
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // 4. Sync I/O: EF Core 9 Cosmos provider throws on sync calls by default.
        //    Existing code uses ToList() / SaveChanges(), so opt-in until migrated to async.
        if (!optionsBuilder.IsConfigured)
        {
            optionsBuilder.ConfigureWarnings(w =>
                w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.CosmosEventId.SyncNotSupported));
        }
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

